import random
from collections import deque

def shortest_cycle_length(adj, n):
    best = float('inf')
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v and parent[v] != u:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < best:
                        best = cycle_len
        if best <= 6:
            break
    return best

def has_cycle_up_to(adj, n, max_len):
    """Check for any cycle of length <= max_len."""
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[start] = 0
        q = deque([start])
        while q:
            u = q.popleft()
            if dist[u] > max_len // 2:
                continue
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v and parent[v] != u:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= max_len:
                        return True
    return False

def greedy_coloring(adj, n):
    color = [-1] * n
    for u in range(n):
        used = set()
        for v in adj[u]:
            if color[v] != -1:
                used.add(color[v])
        c = 0
        while c in used:
            c += 1
        color[u] = c
    return max(color) + 1, color

# Let's try a more careful approach.
# For bipartite graphs, C4 detection: 
# A C4 is u1 - v1 - u2 - v2 - u1 where u1,u2 in left, v1,v2 in right.
# When adding edge (u,v), a C4 is formed if there exists u' in left, v' in right such that
# (u,v') and (u',v') and (u',v) are all edges.

# C6 detection:
# A C6 is u1 - v1 - u2 - v2 - u3 - v3 - u1.
# When adding edge (u,v), a C6 is formed if there's a path of length 5 between u and v.

def try_bipartite_careful(n_left, n_right, target_edges, seed=0):
    n = n_left + n_right
    random.seed(seed)

    adj = [set() for _ in range(n)]
    edges = []

    possible = [(u, v) for u in range(n_left) for v in range(n_left, n)]
    random.shuffle(possible)

    for u, v in possible:
        if len(edges) >= target_edges:
            break

        # Check C4: is there u' != u in left, v' != v in right such that
        # u is connected to v', u' connected to v', u' connected to v?
        has_c4 = False
        for v_prime in adj[u]:
            if v_prime == v:
                continue
            for u_prime in adj[v_prime]:
                if u_prime == u:
                    continue
                if v in adj[u_prime]:
                    has_c4 = True
                    break
            if has_c4:
                break

        if has_c4:
            continue

        # Check C6: is there a path of length 5 between u and v?
        # BFS from u up to distance 4, see if v is reachable at distance 5
        # Actually, we need to check if there's a path of length 5 that doesn't use edge (u,v).
        # Since we haven't added (u,v) yet, any path is fine.

        # BFS limited to depth 5
        dist = [-1] * n
        dist[u] = 0
        q = deque([u])
        has_c6 = False
        while q and not has_c6:
            cur = q.popleft()
            if dist[cur] >= 5:
                continue
            for w in adj[cur]:
                if dist[w] == -1:
                    dist[w] = dist[cur] + 1
                    q.append(w)
                    if w == v:
                        if dist[w] == 5:
                            has_c6 = True
                        break

        if has_c6:
            continue

        # Add edge
        adj[u].add(v)
        adj[v].add(u)
        edges.append((u, v))

    return edges, adj

# Try different splits
for n_left in range(8, 14):
    n_right = 21 - n_left
    for seed in range(100):
        edges, adj = try_bipartite_careful(n_left, n_right, 27, seed=seed)
        if len(edges) >= 27:
            girth = shortest_cycle_length(adj, 21)
            if girth >= 8:
                print(f"Split {n_left}/{n_right}, seed {seed}: {len(edges)} edges, girth {girth}")
                colors_used, coloring = greedy_coloring(adj, 21)
                print(f"Colors: {colors_used}")
                print(f"Edges: {edges}")
                break
    else:
        continue
    break
else:
    print("No bipartite solution found with simple search")
